import { state } from '/static/v2/api.js';
import { hydrateIcons } from '/static/v2/icons.js';
import * as chat from '/static/v2/conversation.js';

state.session = { session_id: 'interaction-fixture', workdir: '/fixture' };
state.view = 'chat';
hydrateIcons();
const history = Array.from({ length: 20 }, (_, i) => ({ role: i % 2 ? 'assistant' : 'user', content: `历史消息 ${i + 1}。\n\n` + '保持正在阅读的位置。'.repeat(18) }));
const run = { sessionId: state.session.session_id, active: true, message: { role: 'assistant', content: '正在整理结果。\n\n文件：`/fixture/成果.pdf`。', thinking: '可滚动的思考记录。\n\n'.repeat(160), segments: [], streaming: true, elapsed: 1 } };
run.message.segments.push({ type: 'tool_result', call_id: 'fixture-command', tool_name: 'terminal.run', status: 'success', content: 'fixture', presentation: {
  kind: 'terminal-run', executionId: 'fixture-command', purpose: 'command', exitCode: 0,
  stdout: { preview: '输出预览', totalBytes: 10000, truncated: true }, stderr: { preview: '', totalBytes: 0 },
} });
chat.renderMessages(history);
run.node = chat.appendMessage(run.message);
if (chat.setupConversationScroll) chat.setupConversationScroll();
else document.querySelector('#conversation').addEventListener('scroll', chat.trackScroll, { passive: true });
chat.bottom(true);
document.querySelector('#session-title').textContent = '流式交互回归 · 独立测试';
document.querySelector('.topbar-actions').innerHTML = '<button id="check" class="primary-button">运行交互验收</button><output id="result">就绪</output>';
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
const results = {};
let ticks = 0;
const stream = setInterval(() => {
  run.message.thinking += `继续检查 ${++ticks}。\n\n`;
  run.message.elapsed += .08;
  chat.paintRun(run);
}, 80);
document.querySelector('#check').onclick = async () => {
  const button = document.querySelector('#check');
  button.disabled = true;
  const area = document.querySelector('#conversation');
  const spinner = run.node.querySelector('.spinner');
  const animation = spinner.getAnimations()[0];
  await delay(2200);
  results.spinner_node_survives_stream = spinner === run.node.querySelector('.spinner');
  results.animation_runs_continuously = animation?.currentTime > 1800;
  chat.bottom(true);
  area.dispatchEvent(new WheelEvent('wheel', { deltaY: -35, bubbles: true }));
  area.scrollTo({ top: area.scrollTop - 35, behavior: 'instant' });
  const nearBottomReading = area.scrollTop;
  await delay(400);
  results.near_bottom_wheel_keeps_user_position = Math.abs(area.scrollTop - nearBottomReading) < 2;
  run.node.querySelector('.activity').open = true;
  await delay(120);
  const body = run.node.querySelector('.activity-body');
  const toolDetail = body.querySelector('.tool-event details');
  toolDetail.open = true;
  await chat.readTerminalOutput(body.querySelector('[data-terminal]'));
  const output = body.querySelector('.terminal-stream pre');
  body.scrollTop = 120;
  await delay(300);
  results.expanded_activity_and_scroll_survive = body === run.node.querySelector('.activity-body') && Math.abs(body.scrollTop - 120) < 2;
  results.tool_details_and_loaded_output_survive = toolDetail.open && output.isConnected && output.textContent.startsWith('FULL_OUTPUT');
  const activeText = run.node.querySelector('.answer p').firstChild;
  const fileLink = run.node.querySelector('.answer [data-file]');
  const activeRange = document.createRange();
  activeRange.setStart(activeText, 0); activeRange.setEnd(activeText, 4);
  getSelection().removeAllRanges(); getSelection().addRange(activeRange);
  run.message.content += '继续生成内容。';
  chat.paintRun(run);
  results.active_answer_selection_survives_appended_text = getSelection().toString() === '正在整理';
  results.file_link_survives_appended_text = fileLink === run.node.querySelector('.answer [data-file]') && fileLink?.dataset.file === '/fixture/成果.pdf';
  getSelection().removeAllRanges();
  chat.bottom(true);
  await delay(100);
  area.dispatchEvent(new WheelEvent('wheel', { deltaY: -35, bubbles: true }));
  area.scrollTo({ top: area.scrollTop - 35, behavior: 'instant' });
  const readingPosition = area.scrollTop;
  await delay(600);
  results.small_upward_scroll_is_not_pulled_back = Math.abs(area.scrollTop - readingPosition) < 2;
  const originalMessage = document.querySelector('#message-2');
  const text = originalMessage.querySelector('.user-content').firstChild;
  const selection = getSelection();
  const range = document.createRange();
  range.setStart(text, 0); range.setEnd(text, 6);
  selection.removeAllRanges(); selection.addRange(range);
  clearInterval(stream);
  run.message.streaming = false;
  chat.paintRun(run);
  chat.renderMessages([...history, run.message], { preserveView: true });
  await delay(100);
  results.finished_run_preserves_history_nodes = document.querySelector('#message-2') === originalMessage;
  results.finished_run_preserves_selection = getSelection().toString() === '历史消息 3';
  results.finished_run_preserves_reading_position = Math.abs(area.scrollTop - readingPosition) < 2;
  selection.removeAllRanges();
  chat.bottom(true);
  const oldBottom = area.scrollTop;
  run.message.content += '\n\n新增回答内容。'.repeat(20);
  chat.paintRun(run);
  results.explicit_bottom_resumes_following = area.scrollTop > oldBottom && area.scrollHeight - area.scrollTop - area.clientHeight < 2;
  document.querySelector('#result').textContent = JSON.stringify({ passed: Object.values(results).every(Boolean), results });
  button.textContent = '验收结束';
};
